    constructor() ERC20("VAI Stablecoin", "VAI") {}

    function mint(address usr, uint256 wad) external {
        _mint(usr, wad);
    }

    function burn(address usr, uint256 wad) external {
        if (usr != msg.sender) {
            _spendAllowance(usr, msg.sender, wad);
        }
        _burn(usr, wad);
    }
}

